bool searchMatrix(vector<vector<int>>& m, int t) {
    if (m.empty() || m[0].empty()) return false;
    long long R = m.size(), C = m[0].size(), lo = 0, hi = R * C;
    while (lo < hi) { long long mid = (lo + hi) / 2; if (m[mid / C][mid % C] < t) lo = mid + 1; else hi = mid; }
    return lo < R * C && m[lo / C][lo % C] == t;
}
